// Flatten the primary URL/domain and attachment info so downstream
// OSINT nodes have simple fields to work with.
const data = $input.item.json;
const urls = (data.urls && data.urls.all_urls) || [];
const domains = (data.urls && data.urls.unique_domains) || [];
let primary_url = urls[0] || '';
let primary_domain = domains[0] || '';
if (!primary_domain && primary_url) {
  try { primary_domain = new URL(primary_url).hostname; } catch (e) {}
}

const rawEmail = $('📨 Fetch Full Email').item.json;
const attachments = rawEmail.attachments || [];
const firstAttachment = attachments[0] || null;

return {
  ...data,
  primary_url,
  primary_domain,
  from_domain: data.email_metadata.from_domain,
  message_id: data.email_metadata.message_id,
  has_attachment: !!firstAttachment,
  attachment_filename: firstAttachment ? (firstAttachment.filename || firstAttachment.name || 'unknown') : null,
  attachment_id: firstAttachment ? (firstAttachment.id || firstAttachment.attachmentId || '') : null
};

const prep = $('🧩 Prepare OSINT Targets').item.json;
const rdap = $input.item.json;
let domain_age_days = null, created_date = null, registrar = null;
try {
  const events = rdap.events || [];
  const reg = events.find(e => e.eventAction === 'registration');
  if (reg) {
    created_date = reg.eventDate;
    domain_age_days = Math.floor((Date.now() - new Date(reg.eventDate).getTime()) / 86400000);
  }
  const registrarEntity = (rdap.entities || []).find(e => (e.roles || []).includes('registrar'));
  registrar = registrarEntity ? (registrarEntity.handle || 'unknown') : null;
} catch (e) {}

return {
  ...prep,
  domain_intel: {
    domain_age_days,
    created_date,
    registrar,
    rdap_lookup_succeeded: !!(rdap && rdap.events)
  }
};

// VirusTotal v3 looks URLs up by an unpadded base64url id
const data = $input.item.json;
function b64url(str) {
  return Buffer.from(str).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
return { ...data, vt_url_id: data.primary_url ? b64url(data.primary_url) : '' };

const prior = $('🔑 Compute VT URL ID').item.json;
const vt = $input.item.json;
let vt_url_analysis = { checked: false, malicious_count: 0, total_engines: 0, categories: [] };
try {
  if (vt.data && vt.data.attributes) {
    const stats = vt.data.attributes.last_analysis_stats || {};
    vt_url_analysis = {
      checked: true,
      malicious_count: stats.malicious || 0,
      suspicious_count: stats.suspicious || 0,
      total_engines: Object.values(stats).reduce((a, b) => a + b, 0),
      categories: Object.values(vt.data.attributes.categories || {}),
      reputation: vt.data.attributes.reputation
    };
  }
} catch (e) {}
return { ...prior, vt_url_analysis };

// URLScan needs ~10-20s to finish rendering, so we don't block the
// triage on the screenshot - we record the submission and link for
// a human/second pass to review, and let the LLM know a scan is pending.
const prior = $('🦠 Parse VT URL Result').item.json;
const scan = $input.item.json;
return {
  ...prior,
  urlscan_submission: {
    submitted: !!(scan && scan.uuid),
    scan_uuid: scan.uuid || null,
    result_url: scan.result || null
  }
};

const prior = $('📷 Parse URLScan Submission').item.json;
const serp = $input.item.json;
const organic = (serp.organic || []).slice(0, 5).map(r => ({ title: r.title, link: r.link, snippet: r.snippet }));
return { ...prior, domain_web_search: organic };

const prior = $('🔀 Has Sender Domain?').item.json;
const rows = $input.all().map(i => i.json);
return { ...prior, sender_allowlisted: rows.length > 0 };

const prior = $('📋 Parse Allowlist Result').item.json;
const results = $input.all().map(i => i.json);
return {
  ...prior,
  sender_prior_emails_count: results.length,
  sender_is_new: results.length === 0
};

const prior = $('📜 Parse Sender History').item.json;
const serp = $input.item.json;
const organic = (serp.organic || []).slice(0, 5).map(r => ({ title: r.title, link: r.link, snippet: r.snippet }));
return { ...prior, sender_web_search: organic };

const crypto = require('crypto');
const item = $input.item;
const binaryKeys = Object.keys(item.binary || {});
let sha256 = null, binaryKey = null;
if (binaryKeys.length > 0) {
  binaryKey = binaryKeys[0];
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
}
return {
  json: { ...item.json, attachment_sha256: sha256, attachment_binary_key: binaryKey },
  binary: item.binary
};

const priorHash = $('🔐 Hash Attachment').item.json;
const extracted = $input.item.json;
const text = (extracted.text || '').toString();
return {
  ...priorHash,
  attachment_text_flags: {
    requests_credentials: /password|login|credential|verify.*account/i.test(text),
    has_urgency: /urgent|immediately|expire|24 hour/i.test(text),
    text_preview: text.substring(0, 250)
  }
};

const prior = $('📄 Parse PDF Text Flags').item.json;
const vt = $input.item.json;
let file_analysis = { checked: false, malicious_count: 0, total_engines: 0, threat_names: [] };
try {
  if (vt.data && vt.data.attributes) {
    const stats = vt.data.attributes.last_analysis_stats || {};
    const results = vt.data.attributes.last_analysis_results || {};
    const names = Object.values(results).filter(r => r.category === 'malicious').map(r => r.result).filter(Boolean);
    file_analysis = {
      checked: true,
      malicious_count: stats.malicious || 0,
      total_engines: Object.values(stats).reduce((a, b) => a + b, 0),
      threat_names: [...new Set(names)].slice(0, 5)
    };
  }
} catch (e) {}
return { ...prior, file_analysis };

const prior = $input.item.json;
return {
  ...prior,
  file_analysis: { checked: false, malicious_count: 0, total_engines: 0, threat_names: [] },
  attachment_text_flags: null
};

const d = $input.item.json;
return {
  email_metadata: d.email_metadata,
  authentication: d.authentication,
  security_flags: d.security_flags,
  urls: d.urls,
  attachments: d.attachments,
  osint: {
    url: {
      target_url: d.primary_url,
      target_domain: d.primary_domain,
      domain_age_days: d.domain_intel ? d.domain_intel.domain_age_days : null,
      registrar: d.domain_intel ? d.domain_intel.registrar : null,
      virustotal: d.vt_url_analysis || null,
      urlscan: d.urlscan_submission || null,
      web_search: d.domain_web_search || []
    },
    attachment: {
      filename: d.attachment_filename,
      sha256: d.attachment_sha256 || null,
      virustotal: d.file_analysis || null,
      text_flags: d.attachment_text_flags || null
    },
    sender: {
      domain: d.from_domain,
      allowlisted: d.sender_allowlisted || false,
      prior_emails_count: d.sender_prior_emails_count,
      is_new_domain_to_us: d.sender_is_new,
      web_search: d.sender_web_search || []
    }
  }
};

// No URL/domain was found in the email body - skip the OSINT calls
// that need one rather than firing malformed requests.
const prior = $input.item.json;
return {
  ...prior,
  domain_intel: {
    domain_age_days: null, created_date: null, registrar: null,
    rdap_lookup_succeeded: false, skipped_reason: 'no primary domain extracted from email'
  },
  vt_url_analysis: { checked: false, malicious_count: 0, total_engines: 0, categories: [], skipped: true },
  urlscan_submission: { submitted: false, scan_uuid: null, result_url: null, skipped: true },
  domain_web_search: []
};

// No sender domain could be parsed from the From address - skip the
// allowlist/history/reputation lookups rather than querying with a blank value.
const prior = $input.item.json;
return {
  ...prior,
  sender_allowlisted: false,
  sender_prior_emails_count: 0,
  sender_is_new: true,
  sender_web_search: []
};

// Attachment had no readable binary / hash couldn't be computed -
// skip the file OSINT lookups rather than querying VirusTotal with a null hash.
const prior = $input.item.json;
return {
  ...prior,
  file_analysis: { checked: false, malicious_count: 0, total_engines: 0, threat_names: [], skipped: true },
  attachment_text_flags: null
};
